{
 "app_name": "spotify",
 "api_name": "search_albums",
 "path": "/albums",
 "method": "GET",
 "description": "Search for albums with a query.",
 "parameters": [
  {
   "name": "query",
   "type": "string",
   "required": false,
   "description": "The search query string.",
   "default": "",
   "constraints": []
  },
  {
   "name": "min_rating",
   "type": "number",
   "required": false,
   "description": "The minimum rating for search results.",
   "default": 0,
   "constraints": [
    "value >= 0.0, <= 5.0"
   ]
  },
  {
   "name": "max_rating",
   "type": "number",
   "required": false,
   "description": "The maximum rating for search results.",
   "default": 5,
   "constraints": [
    "value >= 0.0, <= 5.0"
   ]
  },
  {
   "name": "min_release_date",
   "type": "string",
   "required": false,
   "description": "The minimum release date for search results in YYYY-MM-DD format.",
   "default": "1500-01-01",
   "constraints": []
  },
  {
   "name": "max_release_date",
   "type": "string",
   "required": false,
   "description": "The maximum release date for search results in YYYY-MM-DD format.",
   "default": "3000-01-01",
   "constraints": []
  },
  {
   "name": "min_like_count",
   "type": "integer",
   "required": false,
   "description": "The minimum like count for search results.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "max_like_count",
   "type": "integer",
   "required": false,
   "description": "The maximum like count for search results.",
   "default": 9223372036854775807,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "genre",
   "type": "string",
   "required": false,
   "description": "The genre to filter the albums by.",
   "default": null,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1.0, <= 20.0"
   ]
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the albums by prefixed with +/- to reflect ascending/descending. Valid attributes: rating and release_date. If both query and sort_by are given and non-empty, results will be first ranked by query relevance, then paginated, and will then be sorted by the given attribute within each page.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "album_id": 1,
    "title": "string",
    "genre": "string",
    "artists": [
     {
      "id": 1,
      "name": "string"
     }
    ],
    "rating": 0.0,
    "like_count": 1,
    "review_count": 1,
    "release_date": "2019-01-01T00:00:00",
    "song_ids": [
     1
    ]
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}

